#include "linalg_lapack.hpp"
namespace penta::linalg {
void spectral(const penta_numeric_host_v1* host,const penta_linalg_request_v1& r,penta_linalg_result_v1& result){
    realMatrix(r.a);const auto& a=r.a;const auto m=static_cast<lapack_int>(a.rows),n=static_cast<lapack_int>(a.columns),k=std::min(m,n);if(r.operation!=PENTA_LA_SVD)condition(a,r,result);cancelled(host);
    if(r.operation==PENTA_LA_RANK){result.scalar=static_cast<double>(result.rank);result.converged=1;return;}
    if(r.operation==PENTA_LA_RCOND){result.scalar=result.rcond;result.converged=1;return;}
    if(r.operation==PENTA_LA_COND){if(result.rcond==0)throw Error(PENTA_NUMERIC_DOMAIN,"The matrix condition number is unbounded (singular matrix).");result.scalar=finite(1/result.rcond);result.converged=1;return;}
    auto matrix=copyReal(a);
    if(r.operation==PENTA_LA_SVD){outputValid(result.output[0],a.rows,k);outputValid(result.output[1],k,k);outputValid(result.output[2],a.columns,k);outputValid(result.output[3],k,1);std::vector<double> singular(k),u(static_cast<size_t>(m)*k),vt(static_cast<size_t>(k)*n),s(static_cast<size_t>(k)*k),v(static_cast<size_t>(n)*k);if(k)lapackStatus(LAPACKE_dgesdd(LAPACK_ROW_MAJOR,'S',m,n,matrix.data(),n,singular.data(),u.data(),k,vt.data(),n),"Thin SVD");conditionFromSingular(singular,a,r,result);for(lapack_int i=0;i<k;++i){s[static_cast<size_t>(i)*k+i]=singular[i];for(lapack_int j=0;j<n;++j)v[static_cast<size_t>(j)*k+i]=vt[static_cast<size_t>(i)*n+j];}copyFinite(u,result.output[0]);copyFinite(s,result.output[1]);copyFinite(v,result.output[2]);copyFinite(singular,result.output[3]);result.converged=1;return;}
    require(m==n,"Eigen/Schur decomposition requires a square real matrix.");
    if(r.operation==PENTA_LA_EIGEN){outputValid(result.output[0],n,n);outputValid(result.output[1],n,n);outputValid(result.output[2],n,1);outputValid(result.output[3],n,1);std::vector<double> realValues(n),imagValues(n),vectors(static_cast<size_t>(n)*n),realVectors(vectors.size()),imagVectors(vectors.size());double dummy=0;if(n)lapackStatus(LAPACKE_dgeev(LAPACK_ROW_MAJOR,'N','V',n,matrix.data(),n,realValues.data(),imagValues.data(),&dummy,1,vectors.data(),n),"Eigenvalue decomposition");for(lapack_int j=0;j<n;++j)for(lapack_int i=0;i<n;++i){const auto index=static_cast<size_t>(i)*n+j;if(imagValues[j]==0)realVectors[index]=vectors[index];else if(imagValues[j]>0){require(j+1<n,"Invalid LAPACK conjugate eigenpair.");realVectors[index]=vectors[index];imagVectors[index]=vectors[static_cast<size_t>(i)*n+j+1];}else{require(j>0,"Invalid LAPACK conjugate eigenpair.");realVectors[index]=vectors[static_cast<size_t>(i)*n+j-1];imagVectors[index]=-vectors[index];}}copyFinite(realVectors,result.output[0]);copyFinite(imagVectors,result.output[1]);copyFinite(realValues,result.output[2]);copyFinite(imagValues,result.output[3]);result.converged=1;return;}
    require(r.operation==PENTA_LA_SCHUR,"Unknown spectral operation.");outputValid(result.output[0],n,n);outputValid(result.output[1],n,n);std::vector<double> q(static_cast<size_t>(n)*n),realValues(n),imagValues(n);lapack_int selected=0;if(n)lapackStatus(LAPACKE_dgees(LAPACK_ROW_MAJOR,'V','N',nullptr,n,matrix.data(),n,&selected,realValues.data(),imagValues.data(),q.data(),n),"Real Schur decomposition");copyFinite(q,result.output[0]);copyFinite(matrix,result.output[1]);result.converged=1;
}
}
